drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  01 · index posts by tag★★☆ core
//  concepts: Dictionary · StringComparer · HashSet
// ─────────────────────────────────────────────────────────────────────────
//
//  Build the lookup once instead of scanning every post per request.

using static Bootcamp.Check;

Dictionary<string, List<int>> IndexByTag(IEnumerable<Post> posts)
{
    var index = new Dictionary<string, List<int>>(StringComparer.OrdinalIgnoreCase);
    foreach (var post in posts)
    {
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var raw in post.Tags)
        {
            var tag = raw.Trim();
            if (tag.Length == 0 || !seen.Add(tag)) continue;
            if (!index.TryGetValue(tag, out var ids)) index[tag] = ids = new List<int>();
            ids.Add(post.Id);
        }
    }
    return index;
}

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("tags map to post ids in order", () =>
{
    var idx = IndexByTag(new[] { new Post(1, new[] { "CSharp", "linq" }), new Post(2, new[] { "csharp" }) });
    Eq(idx["csharp"], new[] { 1, 2 });
    Eq(idx["linq"], new[] { 1 });
});

Test("lookups are case-insensitive", () =>
{
    var idx = IndexByTag(new[] { new Post(7, new[] { "EF Core" }) });
    Ok(idx.ContainsKey("ef core"), "lower-case lookup");
    Ok(idx.ContainsKey("EF CORE"), "upper-case lookup");
});

Test("a post repeating a tag is listed once", () =>
{
    var idx = IndexByTag(new[] { new Post(3, new[] { "api", "API", " api " }) });
    Eq(idx["api"], new[] { 3 });
    Eq(idx.Count, 1);
});

Test("blank tags are ignored (boundary)", () =>
{
    var idx = IndexByTag(new[] { new Post(4, new[] { "", "   " }) });
    Eq(idx.Count, 0);
});

Test("no posts gives an empty index", () =>
    Eq(IndexByTag(Array.Empty<Post>()).Count, 0));

drills.explanation:
Give the dictionary a case-insensitive comparer, and use a per-post HashSet with the same comparer to skip repeated tags:

```csharp
var index = new Dictionary<string, List<int>>(StringComparer.OrdinalIgnoreCase);
foreach (var post in posts)
{
    var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    foreach (var raw in post.Tags)
    {
        var tag = raw.Trim();
        if (tag.Length == 0 || !seen.Add(tag)) continue;
        if (!index.TryGetValue(tag, out var ids)) index[tag] = ids = new List<int>();
        ids.Add(post.Id);
    }
}
```

`TryGetValue` gets or creates the list with a single lookup. Lower-casing the keys yourself instead of passing a comparer fails "lookups are case-insensitive": the index holds `ef core`, and a lookup of `EF CORE` finds nothing unless every caller remembers to lower-case too. Without the per-post set, the post tagged `api`, `API` and ` api ` is listed three times, and "a post repeating a tag is listed once" fails.

